#!/usr/bin/env node
/**
 * Reuse a completed release-preview only when GitHub proves the actual main
 * tree is byte-identical to the reviewed PR head, and all authoritative
 * preview gates passed. Any ambiguity, API error, scope change or direct
 * main push FAILS CLOSED to the existing full release validation.
 *
 * This is not a CI skip based on commit messages, labels, or GitHub checks
 * alone. No artifact generated by an untrusted PR controls production.
 */
import { appendFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const SHA = /^[0-9a-f]{40}$/;
const GUARDED_PATH = /^(?:\.github\/workflows\/|scripts\/(?:ci-|test-changed\.|production-gates\.|release-scope\.|version\.|prepare-standalone\.)|tests\/ci-)/;
const REQUIRED_JOBS = ["Release scope", "Release validation", "Release tests and typecheck", "Release performance regression"];

// GitHub may return pull_requests: [] for completed PR runs after branch
// deletion or a squash merge. The exact PR head SHA, source branch and
// repository still uniquely bind the run to the merged PR in this case.
// A populated but inconsistent PR association must NEVER use that fallback.
function authenticatedPreviewRun(run, pr, repository, name, path) {
  if (run?.event !== "pull_request" || run?.name !== name || run?.path !== path
    || run.status !== "completed" || run.conclusion !== "success"
    || run.head_sha !== pr.head.sha || run.head_branch !== pr.head.ref
    || run.head_repository?.full_name !== repository
    || !Array.isArray(run.pull_requests)) return false;
  return run.pull_requests.length === 0 || run.pull_requests.some((ref) =>
    ref.number === pr.number && ref.head?.sha === pr.head.sha && ref.base?.ref === "main");
}

export function assessPreviewReuse({ repository, sha, prs, mainCommit, prCommit, changedFiles, runs, jobsByRun }) {
  if (!SHA.test(sha || "") || !repository) return { reusable: false, reason: "invalid identity" };
  const matching = prs.filter((pr) => pr.merged_at && pr.merge_commit_sha === sha
    && pr.base?.ref === "main" && pr.head?.repo?.full_name === repository
    && SHA.test(pr.head?.sha || "") && pr.labels?.some((label) => label.name === "release-preview")
    && Number.isInteger(pr.changed_files) && pr.changed_files > 0 && pr.changed_files <= 100);
  if (matching.length !== 1) return { reusable: false, reason: "no unique merged preview PR" };
  const pr = matching[0];
  if (!SHA.test(mainCommit?.tree?.sha || "") || mainCommit.tree.sha !== prCommit?.tree?.sha) {
    return { reusable: false, reason: "PR/main source trees differ" };
  }
  if (!Array.isArray(changedFiles) || changedFiles.length !== pr.changed_files
    || changedFiles.some((file) => !file.filename || GUARDED_PATH.test(file.filename))) {
    return { reusable: false, reason: "incomplete or sensitive PR scope" };
  }
  const matchingRuns = runs
    .filter((run) => authenticatedPreviewRun(run, pr, repository, "CI", ".github/workflows/ci.yml"))
    .sort((a, b) => Date.parse(b.updated_at || b.created_at) - Date.parse(a.updated_at || a.created_at));
  const codeqlPassed = runs.some((run) =>
    authenticatedPreviewRun(run, pr, repository, "CodeQL", ".github/workflows/codeql.yml"));
  if (!codeqlPassed) return { reusable: false, reason: "CodeQL not green for exact PR head" };
  for (const run of matchingRuns) {
    const jobs = jobsByRun.get(run.id);
    if (!Array.isArray(jobs)) continue;
    if (REQUIRED_JOBS.every((name) => jobs.some((job) => job.name === name && job.conclusion === "success"))
      && jobs.some((job) => job.name === "Deploy production" && job.conclusion === "skipped")) {
      return { reusable: true, reason: "exact tree and complete green release-preview",
        pr: pr.number, run: run.id };
    }
  }
  return { reusable: false, reason: "no complete green preview for exact PR head" };
}

async function verify({ repository, sha, token }) {
  if (!SHA.test(sha || "") || !/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repository || "") || !token) {
    return { reusable: false, reason: "no trusted GitHub identity" };
  }
  const api = async (path) => {
    const response = await fetch(`https://api.github.com/repos/${repository}${path}`, {
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
      },
      signal: AbortSignal.timeout(8000),
    });
    if (!response.ok) throw new Error(`GitHub HTTP ${response.status}`);
    return response.json();
  };
  const prs = await api(`/commits/${sha}/pulls?per_page=20`);
  const preliminary = prs.filter((pr) => pr.merge_commit_sha === sha && pr.merged_at
    && pr.base?.ref === "main" && pr.head?.repo?.full_name === repository);
  if (preliminary.length !== 1 || preliminary[0].changed_files > 100) {
    return { reusable: false, reason: "not a unique safe PR merge" };
  }
  const pr = await api(`/pulls/${preliminary[0].number}`);
  if (!pr.head?.sha || !SHA.test(pr.head.sha) || !pr.head.ref) {
    return { reusable: false, reason: "missing PR head identity" };
  }
  const [mainCommit, prCommit, changedFiles, workflows] = await Promise.all([
    api(`/git/commits/${sha}`),
    api(`/git/commits/${pr.head.sha}`),
    api(`/pulls/${pr.number}/files?per_page=100`),
    api(`/actions/runs?event=pull_request&head_sha=${pr.head.sha}&per_page=100`),
  ]);
  const runs = workflows.workflow_runs ?? [];
  const matching = runs.filter((run) =>
    authenticatedPreviewRun(run, pr, repository, "CI", ".github/workflows/ci.yml")).slice(0, 6);
  const jobsByRun = new Map();
  await Promise.all(matching.map(async (run) => {
    const result = await api(`/actions/runs/${run.id}/jobs?per_page=100`);
    // More than one page is unusual but cannot prove full gate completion.
    if (result.total_count <= 100) jobsByRun.set(run.id, result.jobs);
  }));
  return assessPreviewReuse({ repository, sha, prs: [pr], mainCommit, prCommit,
    changedFiles, runs, jobsByRun });
}

async function main() {
  let result;
  try {
    if (process.env.GITHUB_EVENT_NAME !== "push" || process.env.GITHUB_REF !== "refs/heads/main") {
      result = { reusable: false, reason: "not a production main push" };
    } else {
      result = await verify({
        repository: process.env.GITHUB_REPOSITORY,
        sha: process.env.GITHUB_SHA,
        token: process.env.GH_TOKEN,
      });
    }
  } catch (error) {
    // GitHub outages, permissions and rate limiting cannot bypass a release gate.
    result = { reusable: false, reason: `verification unavailable (${error instanceof Error ? error.message : "unknown"})` };
  }
  console.log(`[ci] preview reuse: ${JSON.stringify(result)}`);
  if (process.env.GITHUB_OUTPUT) {
    appendFileSync(process.env.GITHUB_OUTPUT, `reuse=${result.reusable ? "true" : "false"}\n`);
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main().catch((error) => { console.error(error); process.exitCode = 1; });
}
